/* @lc app=leetcode id=2512 lang=kotlin */ class Solution { fun topStudents(positive_feedback: Array<String>, negative_feedback: Array<String>, report: Array<String>, student_id: IntArray, k: Int): List<Int> = positive_feedback.toSet().let { p -> negative_feedback.toSet().let { n -> report.map { r -> r.split(" ").map { w -> if (w in p) 3 else if (w in n) -1 else 0 }.sum() }.let { sc -> report.indices.sortedWith(compareBy<Int>({ -sc[it] }, { student_id[it] })).take(k).map { student_id[it] } } } } }